package com.sakan.iptv;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.text.InputType;import java.util.*;

final class ParentalControls {
 private final Activity activity;private final android.content.SharedPreferences prefs;private final Runnable changed;private long until=0;private boolean prompt=false;
 ParentalControls(Activity a,Runnable listener){activity=a;prefs=a.getSharedPreferences("parental",0);changed=listener;}
 private String t(String en,String ar){return "ar".equals(activity.getSharedPreferences("options",0).getString("language","en"))?ar:en;}
 boolean enabled(){return !prefs.getString("pin","").isEmpty();}
 boolean unlocked(){return !enabled()||SystemClock.elapsedRealtime()<until;}
 boolean manages(){return enabled()&&prefs.getBoolean("manage",true)&&!unlocked();}
 Set<String> kinds(){return new HashSet<>(prefs.getStringSet("kinds",Collections.emptySet()));}
 boolean locked(String account,String kind,String category){return enabled()&&!unlocked()&&(kinds().contains(kind)||prefs.getStringSet("categories",Collections.emptySet()).contains(account+":"+kind+":"+category));}
 void require(Runnable success){if(unlocked()){success.run();return;}if(prompt)return;long wait=prefs.getLong("retryAfter",0)-System.currentTimeMillis();if(wait>0){Toast.makeText(activity,t("Try the PIN again in ","أعد محاولة الرقم بعد ")+(wait/1000+1)+t(" seconds"," ثانية"),1).show();return;}prompt=true;EditText input=new EditText(activity);input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);input.setHint(t("PIN","الرقم السري"));AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(t("Parental PIN","الرقم السري للرقابة")).setView(input).setPositiveButton(t("Unlock","فتح"),null).setNegativeButton(t("Cancel","إلغاء"),null).create();dialog.setOnDismissListener(d->prompt=false);dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{if(PinHash.verify(input.getText().toString(),prefs.getString("pin",""))){until=SystemClock.elapsedRealtime()+5*60*1000;prefs.edit().putInt("failures",0).remove("retryAfter").apply();dialog.dismiss();changed.run();success.run();}else{int count=prefs.getInt("failures",0)+1;long pause=count>=5?Math.min(300000,30000L*(count-4)):0;prefs.edit().putInt("failures",count).putLong("retryAfter",System.currentTimeMillis()+pause).apply();input.setError(t("Incorrect PIN","الرقم غير صحيح"));if(pause>0)dialog.dismiss();}}catch(Exception e){input.setError(t("PIN could not be checked","تعذر التحقق من الرقم"));}}));dialog.show();}
 void settings(String account,String kind,String category){if(enabled()&&!unlocked()){require(()->settings(account,kind,category));return;}if(!enabled()){create(()->settings(account,kind,category));return;}boolean hasCategory=account!=null&&category!=null&&!category.equals("*")&&!category.isEmpty();String categoryKey=account+":"+kind+":"+category;String[] labels=hasCategory?new String[]{t("Protect account changes and settings","حماية تعديل الحسابات والإعدادات"),t("Lock live TV","قفل البث المباشر"),t("Lock movies","قفل الأفلام"),t("Lock series","قفل المسلسلات"),t("Lock this category","قفل التصنيف الحالي")}:new String[]{t("Protect account changes and settings","حماية تعديل الحسابات والإعدادات"),t("Lock live TV","قفل البث المباشر"),t("Lock movies","قفل الأفلام"),t("Lock series","قفل المسلسلات")};Set<String> locks=kinds(),categories=new HashSet<>(prefs.getStringSet("categories",Collections.emptySet()));boolean[] values=new boolean[labels.length];values[0]=prefs.getBoolean("manage",true);values[1]=locks.contains("live");values[2]=locks.contains("vod");values[3]=locks.contains("series");if(hasCategory)values[4]=categories.contains(categoryKey);new AlertDialog.Builder(activity).setTitle(t("Parental controls","الرقابة الأبوية")).setMultiChoiceItems(labels,values,(d,w,v)->values[w]=v).setPositiveButton(t("Save and lock","حفظ وقفل"),(d,w)->{Set<String> selected=new HashSet<>();if(values[1])selected.add("live");if(values[2])selected.add("vod");if(values[3])selected.add("series");if(hasCategory){if(values[4])categories.add(categoryKey);else categories.remove(categoryKey);}prefs.edit().putBoolean("manage",values[0]).putStringSet("kinds",selected).putStringSet("categories",categories).apply();until=0;changed.run();}).setNeutralButton(t("Disable PIN","إلغاء الرقم السري"),(d,w)->{prefs.edit().clear().apply();until=0;changed.run();}).setNegativeButton(t("Cancel","إلغاء"),null).show();}
 private void create(Runnable next){LinearLayout fields=new LinearLayout(activity);fields.setOrientation(1);fields.setPadding(32,8,32,8);EditText first=new EditText(activity),confirm=new EditText(activity);first.setInputType(18);confirm.setInputType(18);first.setHint(t("New PIN · 4–8 digits","رقم جديد · 4–8 أرقام"));confirm.setHint(t("Confirm PIN","تأكيد الرقم"));fields.addView(first);fields.addView(confirm);AlertDialog d=new AlertDialog.Builder(activity).setTitle(t("Create parental PIN","إنشاء رقم سري")).setView(fields).setPositiveButton(t("Save","حفظ"),null).setNegativeButton(t("Cancel","إلغاء"),null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String pin=first.getText().toString();if(!pin.equals(confirm.getText().toString())||!pin.matches("[0-9]{4,8}")){confirm.setError(t("Enter matching 4–8 digit PINs","أدخل رقمين متطابقين من 4–8 أرقام"));return;}try{prefs.edit().putString("pin",PinHash.create(pin)).putBoolean("manage",true).apply();until=SystemClock.elapsedRealtime()+300000;d.dismiss();changed.run();next.run();}catch(Exception e){first.setError(t("Could not save PIN","تعذر حفظ الرقم"));}}));d.show();}
 void lockNow(){until=0;changed.run();}
}
